"""Self-contained result page generated only from the completed model seal."""
import collections,json,shutil
from pathlib import Path
from calibrate256_fine_r1 import BASE,load,save,sha
def main():
    out=BASE/'iter60-fine-model-r1';r=load(out/'report.json');t=load(out/'outer-timeline.json');items=[]
    for b in load(out/'bindings.json'):
        g=load(Path(b['graph']));stats=collections.defaultdict(lambda:dict(nodes=0,cost_sum_ms=0))
        for k,n in g.items():stats[n.get('kind','UNSPECIFIED')]['nodes']+=1;stats[n.get('kind','UNSPECIFIED')]['cost_sum_ms']+=n['cost_ms']
        items.append(dict(stage=b['stage'],mb=b['mb'],phase=b['phase'],duration_ms=b['expected_ms'],kinds=dict(stats)))
    data=dict(report=r,timeline=t,inventory=items);save(out/'cost-inventory.json',items)
    template='''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>256卡iter60 · 详细DAG标定与回放</title><style>body{font:16px/1.7 system-ui;background:#eef2f6;color:#172033;max-width:1320px;margin:24px auto;padding:0 16px}section{background:white;border-radius:14px;margin:18px 0;padding:24px}h1{font-size:29px}h2{font-size:22px}.cards{display:flex;flex-wrap:wrap;gap:16px}.card{background:#edf3fa;border-radius:8px;padding:16px;min-width:150px}.card b{display:block;font-size:27px}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:10px;border-bottom:1px solid #ddd;text-align:left}a{color:#2563eb}.flow{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.box{background:#dbeafe;padding:15px;border-radius:8px}.comm{background:#ffedd5}.note{color:#5e6c80}.scroll{overflow:auto}svg{min-width:900px;width:100%}select{padding:8px;margin:5px}pre{white-space:pre-wrap}</style><section><nav><a href="../iter60-calibration-r1/">112单元覆盖审计</a> · <a href="../iter60-dag-alignment-r1/">精确依赖定义</a> · <a href="../prediction-overview-r3/">封存32→256外推</a></nav><h1>256卡iter60：同轮详细DAG标定与回放</h1><p><b>使用256卡iter60的参数，回放同一轮。</b>中间F/B保留计算、CP、EP、重计算、真正反向及保留间隔；首尾整块和PP接口保持同一建模层次。以下是校准回放结果，不是独立预测精度。</p><h2>训练主体：首F设备开始 → Profiler结束</h2><div class="cards" id="cards"></div><div class="scroll" id="bars"></div><table id="metrics"></table><p class="note">启动窗口不在此评估范围。MFU沿用同一有效FLOPs/峰值口径，由对应耗时换算。主结果仍采用原模型的rank0参考窗口，不冒充全rank makespan验证。</p></section><section><h2>① 从参数到整轮结果</h2><div class="flow"><div class="box">256 iter60<br>CPU/GPU/通信组证据</div>→<div class="box">逐节点成本＋保留间隔<br>同一F/B语义与依赖</div>→<div class="box comm">PP消息关联<br>首尾块与尾部参数</div>→<div class="box">DAG重新调度<br>训练主体时间 → MFU</div></div><p>中间stage的F/B外壳成本置0，详细子图接管完成点。两组EP8分别完成标定检查，主模型使用首组链；没有在每个F/B后强加两组全局barrier。</p><h3>16-stage 1F1B回放形状</h3><p>蓝：F，紫：B；横轴为训练主体起点后的毫秒。PP通过消息依赖连接，不把所有通信时长直接相加。</p><div class="scroll" id="schedule"></div></section><section><h2>② 一个中间F/B成本块</h2><div class="flow"><div class="box">F：四层<br>Attention/CP → EP分发 → 专家 → EP合并 → 层尾</div><div class="box">B：四层<br>前向重计算 → MoE梯度 → Attention梯度/CP</div></div><p><a href="../deepep-fb-structure-r1/">共同F/B详细结构</a> · <a href="../iter60-f-layer-binding-r1/">256首层八卡实测绑定</a></p><select id="stage"></select><select id="mb"></select><select id="phase"><option>F</option><option>B</option></select><p id="block"></p><table id="inventory"></table><p class="note">表中是节点参数分组累计量，会有跨卡并行，不能加总当F/B耗时。就绪与间隔仍是标定参数，不是已识别的纯等待或网络服务。</p></section><section><h2>③ 这次修正了什么</h2><ul><li>以CPU标记、correlation及通信组核对CP身份，避免依赖文件排列顺序。</li><li>对CPU输入明确为0的专家工作保留零成本逻辑节点；没有伪造GPU事件。</li><li>保留一版共同图修正：移除15条V输入拷贝等待先前CP完成的条件边；原32卡全部源出口仍保持不变。</li><li>一处同stream拷贝重叠采用显式区间并集计费，原始跨度和重叠账本保留；不是把任意负依赖参数裁零。</li></ul><p>因此这是新候选的同轮回放，原32→256冻结模型和外推结果没有被覆盖。尾部570个活动沿5条stream计费，跨stream及全rank就绪仍通过显式保留参数表达。</p></section><section><h2>④ 冻结证据与复现</h2><p>覆盖14个中间stage × 两组EP8 × 四MB，共112个F/B标定单元。主图插入112个详细F/B子图。其余首尾块、PP、尾部均有独立参数来源。</p><pre>python3 workflow/data_foundation/replay256_iter60_fine_r1.py results/data-foundation/iter60-fine-model-r1</pre><p>回放只需冻结图，不必重新扫描trace。重新标定需要本地原始数据和清单中的代码版本。</p><a href="report.json">结果</a> · <a href="bindings.json">参数绑定</a> · <a href="coverage.json">完整覆盖</a> · <a href="manifest.json">输入与结果哈希</a> · <a href="graph.json.gz">冻结DAG下载</a><details><summary>适用范围与未证明事项</summary><pre id="limits"></pre></details></section><script>const D=__DATA__,R=D.report,$=id=>document.getElementById(id),fmt=(x,n=3)=>x.toFixed(n),signed=x=>(x>=0?'+':'')+fmt(x);$('cards').innerHTML=[['回放时间',fmt(R.body.replay_ms/1000)+' s'],['实测时间',fmt(R.body.truth_ms/1000)+' s'],['耗时误差',signed(R.body.signed_error_percent)+'%'],['回放 / 实测MFU',fmt(R.body.replay_mfu_percent)+'% / '+fmt(R.body.truth_mfu_percent)+'%']].map(([a,b])=>`<div class="card">${a}<b>${b}</b></div>`).join('');let bar='<svg viewBox="0 0 1240 120">';const scale=1050/Math.max(R.body.replay_ms,R.body.truth_ms);[['回放',R.onef1b.replay_ms,R.tail_ms],['实测',R.onef1b.truth_ms,R.body.truth_ms-R.onef1b.truth_ms]].forEach(([label,one,tail],i)=>{const y=10+i*50;bar+=`<text x="0" y="${y+25}">${label}</text><rect x="90" y="${y}" width="${one*scale}" height="34" fill="#5687cf"/><rect x="${90+one*scale}" y="${y}" width="${tail*scale}" height="34" fill="#e9a052"/><text x="105" y="${y+24}" fill="white">1F1B ${fmt(one/1000)} s</text>`});$('bars').innerHTML=bar+'</svg>';$('metrics').innerHTML='<tr><th>阶段</th><th>回放ms</th><th>实测ms</th><th>有符号耗时误差</th></tr>'+[['1F1B',R.onef1b.replay_ms,R.onef1b.truth_ms],['尾部更新与同步',R.tail_ms,R.body.truth_ms-R.onef1b.truth_ms]].map(([k,p,t])=>`<tr><td>${k}</td><td>${fmt(p)}</td><td>${fmt(t)}</td><td>${signed(100*(p/t-1))}%</td></tr>`).join('');let svg='<svg viewBox="0 0 1240 650">';const sx=1100/R.onef1b.replay_ms;for(let s=0;s<16;s++){let y=10+s*36;svg+=`<text x="0" y="${y+20}">PP${s}</text>`;for(let m=0;m<4;m++)for(const ph of ['F','B']){const b=D.timeline[`s${s}:${ph}${m}`];svg+=`<rect x="${85+b.start_ms*sx}" y="${y}" width="${Math.max(.3,(b.end_ms-b.start_ms)*sx)}" height="26" fill="${ph==='F'?'#5687cf':'#9774b8'}"><title>PP${s} ${ph}${m}：${fmt(b.start_ms)}–${fmt(b.end_ms)} ms</title></rect>`}}for(let j=0;j<=5;j++)svg+=`<text x="${85+j*220}" y="610">${fmt(j*R.onef1b.replay_ms/5,0)} ms</text>`;$('schedule').innerHTML=svg+'</svg>';for(let s=1;s<=14;s++)$('stage').add(new Option('PP'+s,s));for(let m=0;m<4;m++)$('mb').add(new Option('MB'+m,m));function draw(){const x=D.inventory.find(x=>x.stage==$('stage').value&&x.mb==$('mb').value&&x.phase==$('phase').value);$('block').textContent=`该F/B子图完成时间：${fmt(x.duration_ms)} ms`;$('inventory').innerHTML='<tr><th>成本类型</th><th>节点数</th><th>参数累计ms（不可直接相加）</th></tr>'+Object.entries(x.kinds).map(([k,v])=>`<tr><td>${k}</td><td>${v.nodes}</td><td>${fmt(v.cost_sum_ms)}</td></tr>`).join('')}for(const id of ['stage','mb','phase'])$(id).onchange=draw;draw();$('limits').textContent=R.limits.join('\n');</script>'''
    template=template.replace("join('\n')",'join(String.fromCharCode(10))')
    template=template.replace('<a href="report.json">结果</a>','<a href="provenance.json">代码与原始数据来源</a> · <a href="code-and-adapters.tar.gz">代码及适配器快照</a> · <a href="report.json">结果</a>')
    (out/'index.html').write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/')))
    # Presentation files have a separate seal; the model manifest remains intact.
    save(out/'presentation-manifest.json',dict(code_sha256=sha(Path(__file__)),model_report_sha256=sha(out/'report.json'),outputs={n:sha(out/n) for n in ['index.html','cost-inventory.json']}))
    web=Path('/home/zjb/Desktop/worktrees/mfu-w37-v610/results/data-foundation/2111-blocks-ui-r1/df-v001')/out.name;web.mkdir(exist_ok=True)
    for p in out.iterdir():
        if p.is_file():shutil.copy2(p,web/p.name)
    print('http://192.168.8.16:43312/df-v001/iter60-fine-model-r1/')
if __name__=='__main__':main()
